/** Below this, folding costs more than it saves — three rows of the same thing
 * is where a loop starts reading as noise. */
const GROUP_MIN_RUN = 3;

/**
 * Fold adjacent runs of identical leaf siblings into one row.
 *
 * "Identical" means same parent, same depth, same name, same type. Two rules
 * keep the feature from hiding what you came for: a run containing an errored or
 * aborted span never folds, and spans with children never fold (a repeated
 * sub-agent keeps its subtree). Runs the reader has expanded pass through
 * unfolded.
 */
function groupRepeatedSiblings(
  rows: SpanRow[],
  expanded: ReadonlySet<string>,
): Row[] {
  const out: Row[] = [];
  let i = 0;
  while (i < rows.length) {
    const head = rows[i];
    const foldable = (r: SpanRow) =>
      !r.hasChildren &&
      r.span.status !== "error" &&
      r.span.status !== "aborted";
    let end = i + 1;
    if (foldable(head)) {
      while (
        end < rows.length &&
        foldable(rows[end]) &&
        rows[end].depth === head.depth &&
        rows[end].span.parentSpanId === head.span.parentSpanId &&
        rows[end].span.name === head.span.name &&
        rows[end].span.spanType === head.span.spanType
      ) {
        end++;
      }
    }
    const run = end - i;
    const key = `${head.span.parentSpanId ?? "root"}|${head.span.name}|${head.span.spanId}`;
    if (run >= GROUP_MIN_RUN) {
      const isExpanded = expanded.has(key);
      out.push({
        kind: "group",
        key,
        depth: head.depth,
        spans: rows.slice(i, end).map((r) => r.span),
        expanded: isExpanded,
      });
      if (isExpanded) for (let j = i; j < end; j++) out.push(rows[j]);
    } else {
      for (let j = i; j < end; j++) out.push(rows[j]);
    }
    i = end;
  }
  return out;
}

export type TimelineReveal = "hold" | "play";

/** How long the whole trace takes to grow in when `reveal` plays. */
export const TIMELINE_REVEAL_SECONDS = 1.2;

// The grow-in replays the trace: each bar starts at its span's offset and
// takes its duration, both scaled so the whole trace fits the reveal window.
// Bars grow at a constant rate, so it's a plain transition on scaleX with the
// span's own timing; the tiny ones get a floor so they don't pop. Holding
// keeps a bar at zero width until the reveal plays.
function revealStyle(
  reveal: TimelineReveal | undefined,
  offsetFraction: number,
  durationFraction: number,
): CSSProperties | undefined {
  if (!reveal) return undefined;
  const seconds = Math.max(0.15, durationFraction * TIMELINE_REVEAL_SECONDS);
  const delay = offsetFraction * TIMELINE_REVEAL_SECONDS;
  return {
    transformOrigin: "left",
    transform: reveal === "play" ? "scaleX(1)" : "scaleX(0)",
    transition:
      reveal === "play" ? `transform ${seconds}s linear ${delay}s` : "none",
  };
}

